"use strict";(self.webpackChunkclearhire_docs=self.webpackChunkclearhire_docs||[]).push([["1152"],{48(e){e.exports=JSON.parse('{"items":[{"title":"ClearHire Changelog: Versions and Notable Releases","description":"A high-level, honest changelog for ClearHire \u2014 the 2.15 rebuild on a new backend, what it added and dropped, and the 1.12.x line before it.","permalink":"/changelog","updatedAt":"2026-10-29T12:35:12.000Z","group":"start","tags":[]},{"title":"ClearHire Paid Plans: Requesting Pro or Team in the App","description":"ClearHire\'s Pro and Team plans are requested in the app and set up on your account by the ClearHire team. Here is how a request works and what you see after it.","permalink":"/features/paid-plans","updatedAt":"2026-10-29T12:35:12.000Z","group":"features","tags":[]},{"title":"ClearHire on a Phone: The App View, Tab Bar and Account Sheet","description":"On a phone ClearHire opens as an app, with a top bar, a tab bar and one action under your thumb. Here is what changes on a phone and what stays the same.","permalink":"/features/phone-app-view","updatedAt":"2026-10-28T17:23:26.000Z","group":"features","tags":[]},{"title":"ClearHire Page Tours and the How ClearHire Works Page","description":"ClearHire\'s page tours walk you through one page at a time, and the How ClearHire works page covers the product in six steps. Here is how both work.","permalink":"/features/page-tours-and-walkthrough","updatedAt":"2026-10-25T01:39:03.000Z","group":"features","tags":[]},{"title":"ClearHire Resume Builder: Templates, PDF, and DOCX","description":"The ClearHire resume builder turns your profile into formatted CVs with multiple templates, section control, and PDF or DOCX export \u2014 all free and in-browser.","permalink":"/features/resume-builder","updatedAt":"2026-09-26T14:03:39.000Z","group":"features","tags":[]},{"title":"Export a ClearHire Resume as PDF or DOCX Step by Step","description":"Step-by-step guide to exporting a ClearHire resume as PDF or DOCX, when to choose each format, and how to fix common export and formatting problems.","permalink":"/guides/export-resume-pdf-docx","updatedAt":"2026-09-26T14:03:39.000Z","group":"guides","tags":[]},{"title":"How to Request Employment Verification in ClearHire","description":"A step-by-step guide to requesting employment verification in ClearHire \u2014 how to send a request, what the employer sees, and how the request timeout behaves.","permalink":"/guides/request-employment-verification","updatedAt":"2026-09-26T14:03:39.000Z","group":"guides","tags":[]},{"title":"ClearHire: Verified-Employment Resume Builder","description":"ClearHire is a resume builder and verified-employment job platform where past employers confirm your roles. Learn what it does, who it serves, and its limits.","permalink":"/intro","updatedAt":"2026-09-26T14:03:39.000Z","group":"start","tags":[]},{"title":"About the ClearHire Team: An Independent Developer","description":"ClearHire is built and maintained by an independent developer, the ClearHire team. What that means for you, where the other apps are, and how to get in touch.","permalink":"/about-the-author","updatedAt":"2026-09-26T11:30:51.000Z","group":"start","tags":[]},{"title":"ClearHire FAQ: Pricing, Accounts, Verification, Data","description":"Answers to common ClearHire questions about pricing, accounts, employment verification, privacy, resume formats, platforms, account deletion, and who built it.","permalink":"/faq","updatedAt":"2026-09-26T11:30:51.000Z","group":"start","tags":[]},{"title":"Analytics in ClearHire: Profile Views and Downloads","description":"Analytics in ClearHire show your profile views, resume downloads, and application progress, turning job-search activity into signals you can act on.","permalink":"/features/analytics","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Application Tracking in ClearHire: Applied to Offer","description":"Application tracking in ClearHire organizes every job you apply to through stages from applied to offer, so you always know where each opportunity stands.","permalink":"/features/applications-tracking","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"ClearHire Career Tools: ATS Checker, Cover Letters","description":"ClearHire career tools include an ATS resume checker, cover-letter and bio generators, interview prep, salary insights, coding challenges, and career paths.","permalink":"/features/career-tools","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Company Reviews in ClearHire: Tied to Real Employment","description":"Company reviews in ClearHire are mutual and tied to a verified employment link, so feedback comes from people who actually worked together. Here is how.","permalink":"/features/company-reviews","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Employment Verification in ClearHire: How It Works","description":"Employment verification in ClearHire lets a past employer confirm a role on your profile, adding a countersignature. Learn the request flow, timeout, and its limits.","permalink":"/features/employment-verification","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"ClearHire for Companies: Post Jobs, Verify, and Hire","description":"ClearHire for companies covers company profiles, job posting, applicant tracking, talent search, employee reviews, and employment verification in one place.","permalink":"/features/for-companies","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Job Search in ClearHire: Filters, Alerts, Saved Searches","description":"Job search in ClearHire finds roles with filters for location, remote, salary, and skills, plus saved searches and job alerts. See how it works and its limits.","permalink":"/features/job-search","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"ClearHire Notifications and Emails: In-App, Push, and Email","description":"How ClearHire keeps you informed \u2014 in-app notifications for your activity, system announcements with three levels of loudness, optional receive-only push, and a few transactional emails.","permalink":"/features/notifications","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Profile Management in ClearHire: One Career Record","description":"Profile management in ClearHire keeps your career in seven structured sections that feed resumes, job search, and verification. See how it works and its limits.","permalink":"/features/profile-management","updatedAt":"2026-09-26T11:30:51.000Z","group":"features","tags":[]},{"title":"Build Your First Resume in ClearHire: Step by Step","description":"Learn to build your first resume in ClearHire \u2014 pick a template, choose profile sections, preview the layout, and export to PDF or DOCX in a few steps.","permalink":"/getting-started/build-your-first-resume","updatedAt":"2026-09-26T11:30:51.000Z","group":"getting-started","tags":[]},{"title":"Create Your ClearHire Profile: 7 Sections Explained","description":"Your ClearHire profile has seven sections that feed every resume and job match. Learn what each section captures, plus tips for completeness and privacy.","permalink":"/getting-started/create-your-profile","updatedAt":"2026-09-26T11:30:51.000Z","group":"getting-started","tags":[]},{"title":"ClearHire Quick Start: Account, Profile, and Resume","description":"A quick-start guide to ClearHire \u2014 create an account, complete your profile, and build and export your first resume in a few short, numbered steps.","permalink":"/getting-started/quick-start","updatedAt":"2026-09-26T11:30:51.000Z","group":"getting-started","tags":[]},{"title":"ATS Resume Checker in ClearHire: How to Use It Well","description":"Learn what an ATS is, how the ClearHire ATS resume checker scores keyword alignment against a job, and how to improve your resume \u2014 guidance, not a guarantee.","permalink":"/guides/ats-resume-checker","updatedAt":"2026-09-26T11:30:51.000Z","group":"guides","tags":[]},{"title":"Exporting or Deleting Your ClearHire Data and Account","description":"How to export your ClearHire data and how to delete your account and data using the in-app account-deletion flow, with a pointer to the full privacy policy.","permalink":"/guides/data-export-and-deletion","updatedAt":"2026-09-26T11:30:51.000Z","group":"guides","tags":[]},{"title":"ClearHire Privacy Summary: What It Stores and Shares","description":"A plain-language summary of what ClearHire stores, the providers it uses, how verification data is shared, and your export and deletion rights.","permalink":"/privacy","updatedAt":"2026-09-26T11:30:51.000Z","group":"start","tags":[]},{"title":"ClearHire and Browser Extensions: There Is No Extension","description":"ClearHire does not ship a browser extension. An earlier prototype captured LinkedIn profiles and auto-filled application forms; it was never published and is not part of ClearHire today.","permalink":"/features/browser-extension","updatedAt":"2026-09-05T13:57:55.000Z","group":"features","tags":[]},{"title":"Challenges, Badges and Levels in ClearHire","description":"ClearHire has challenges, badges, levels and an opt-in leaderboard. Points come from finishing a challenge, never from opening the app, and there is no streak to break.","permalink":"/features/gamification","updatedAt":"2026-09-05T13:57:55.000Z","group":"features","tags":[]}],"newest":"2026-10-29T12:35:12.000Z"}')}}]);